@startuml

class Patient {
  + name : string
  + symptoms : string[]
}

class Doctor {
  + name : string
  + speciality : string
}

class Diagnosis {
  + id : int
  + description : string
  + priorityScore : PriorityScore
  + stage : TreatmentStage
}

enum PriorityScore {
  High
  Low
}

enum TreatmentStage {
  Stage1
  Stage2
  Stage3
}

class TreatmentPlan {
  + id : int
  + treatments : Treatment[]
}

class Treatment {
  + id : int
  + description : string
  + stage : TreatmentStage
  + consentRequired : boolean
}

class Nurse {
  + name : string
}

class Hospital {
  + name : string
  + doctors : Doctor[]
  + patients : Patient[]
  + treatments : Treatment[]
}

Doctor "1" -- "*" Diagnosis
Patient "1" -- "*" Diagnosis
Diagnosis "1" -- "0..1" TreatmentPlan
TreatmentPlan "1" -- "*" Treatment
Nurse "1" -- "*" Patient
Hospital "1" -- "*" Doctor
Hospital "1" -- "*" Patient
Hospital "1" -- "*" Treatment

@enduml

